#!/bin/bash
# PlotNua · @@TITLE@@ · rollback (founder decision only).
# Generated by atlas-tools/release/make-release-scripts.py. Reverts the release commit(s) with new commits,
# returning production's content exactly to @@MAIN_SHORT@@. Never resets or force-pushes. Asks you to confirm.
set -u
REPO="${PLOTNUA_REPO:-$HOME/Documents/PlotNua/04 Deploy/plotnua-grower-release}"
REL=@@REL@@; MAIN0=@@MAIN@@
cd "$REPO" || exit 1; git fetch -q origin
[ "$(git rev-parse origin/main)" = "$REL" ] || { echo "REFUSED: main is not ${REL:0:7} -- nothing pushed"; exit 1; }
[ -t 0 ] && [ -r /dev/tty ] || { echo "REFUSED: the rollback needs you at the keyboard to confirm"; exit 1; }
printf "This reverts PRODUCTION to %s's content. Type  ROLLBACK %s  to confirm: " "${MAIN0:0:7}" "${REL:0:7}"
read -r ANSWER </dev/tty; [ "$ANSWER" = "ROLLBACK ${REL:0:7}" ] || { echo "REFUSED: not confirmed"; exit 1; }
W="$(mktemp -d)"; git worktree add -q --detach "$W" "$REL" && cd "$W" &&
git revert --no-edit "$MAIN0..$REL" >/dev/null && [ -z "$(git diff "$MAIN0" HEAD --stat)" ] &&
git push origin HEAD:refs/heads/main && echo "ROLLED BACK: main content is again ${MAIN0:0:7} (revert commits on top)"
